-- =============================================================================
-- Bank Transactions DWH — analytical queries (OLAP over the star schema)
-- Each query is annotated with the OLAP operation(s) it demonstrates:
-- slice, dice, drill-down, drill-through, pivot, ranking/window functions.
-- Dates below assume the sample data generated by data/generate_sample_data.py
-- (which spans 2024-2025) — adjust the year/quarter filters if you loaded
-- a different period.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Volume and turnover by service channel for a month
--    OLAP operations: slice (fixed month) + dice (group by channel)
-- -----------------------------------------------------------------------------
SELECT ch.channel_name                    AS "channel",
       COUNT(*)                           AS "transaction_count",
       SUM(f.amount)                      AS "total_amount"
FROM fact_transactions f
JOIN dim_date d    ON f.date_id = d.date_id
JOIN dim_channel ch ON f.channel_id = ch.channel_id
WHERE d.year = 2025 AND d.month = 10
GROUP BY ch.channel_name
ORDER BY SUM(f.amount) DESC;

-- -----------------------------------------------------------------------------
-- 1b. Same report, drilled down one level: channel x transaction type
--     OLAP operation: drill-down
-- -----------------------------------------------------------------------------
SELECT ch.channel_name, t.type_name,
       COUNT(*)      AS txn_count,
       SUM(f.amount) AS total_amount
FROM fact_transactions f
JOIN dim_date d              ON f.date_id = d.date_id
JOIN dim_channel ch          ON f.channel_id = ch.channel_id
JOIN dim_transaction_type t  ON f.type_id = t.type_id
WHERE d.year = 2025 AND d.month = 10
GROUP BY ch.channel_name, t.type_name
ORDER BY ch.channel_name, total_amount DESC;

-- -----------------------------------------------------------------------------
-- 2. Top-5 customers by transaction volume for the year
--    OLAP operation: ranking via window function (RANK)
-- -----------------------------------------------------------------------------
SELECT cus.full_name, cus.segment,
       SUM(f.amount) AS total_amount,
       RANK() OVER (ORDER BY SUM(f.amount) DESC) AS rnk
FROM fact_transactions f
JOIN dim_date d       ON f.date_id = d.date_id
JOIN dim_customer cus ON f.customer_id = cus.customer_id
WHERE d.year = 2025
GROUP BY cus.customer_id, cus.full_name, cus.segment
ORDER BY total_amount DESC
LIMIT 5;

-- -----------------------------------------------------------------------------
-- 3. Distribution of transactions by type with average ticket size
--    OLAP operation: aggregation (COUNT/SUM/AVG)
-- -----------------------------------------------------------------------------
SELECT t.type_name              AS "transaction_type",
       COUNT(*)                 AS "count",
       SUM(f.amount)            AS "total_amount",
       AVG(f.amount)            AS "average_amount"
FROM fact_transactions f
JOIN dim_transaction_type t ON f.type_id = t.type_id
WHERE f.transaction_time BETWEEN '2025-01-01' AND '2025-12-31'
GROUP BY t.type_name
ORDER BY SUM(f.amount) DESC;

-- -----------------------------------------------------------------------------
-- 4. Channel x quarter matrix ("pivot")
--    OLAP operation: pivot via conditional aggregation (CASE WHEN)
-- -----------------------------------------------------------------------------
SELECT ch.channel_name,
       SUM(CASE WHEN d.quarter = 1 THEN f.amount ELSE 0 END) AS q1,
       SUM(CASE WHEN d.quarter = 2 THEN f.amount ELSE 0 END) AS q2,
       SUM(CASE WHEN d.quarter = 3 THEN f.amount ELSE 0 END) AS q3,
       SUM(CASE WHEN d.quarter = 4 THEN f.amount ELSE 0 END) AS q4
FROM fact_transactions f
JOIN dim_date d     ON f.date_id = d.date_id
JOIN dim_channel ch ON f.channel_id = ch.channel_id
WHERE d.year = 2025
GROUP BY ch.channel_name;

-- =============================================================================
-- Appendix — extended queries: window functions, conditional aggregation,
-- multi-dimensional breakdowns, drill-through
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 5. Share of transactions processed under 5 seconds
--    OLAP operation: conditional aggregation (SLA-style metric).
--    Requires a processing_time interval column — not part of the base
--    schema in 01_schema_postgresql.sql; add it if you track SLA timing.
