-- -----------------------------------------------------------------------------
-- 6. Monthly trend for one customer segment
--    OLAP operation: drill-down over time
-- -----------------------------------------------------------------------------
SELECT d.year, d.month,
       COUNT(*)      AS txn_count,
       SUM(f.amount) AS total_amount
FROM fact_transactions f
JOIN dim_date d     ON f.date_id = d.date_id
JOIN dim_customer c ON f.customer_id = c.customer_id
WHERE c.segment = 'Mass Market' AND d.year = 2025
GROUP BY d.year, d.month
ORDER BY d.year, d.month;

-- -----------------------------------------------------------------------------
-- 7. Slice-and-dice: transfer volume by customer region, Q1 2025 only
--    OLAP operations: slice (quarter + type) + dice (group by region)
-- -----------------------------------------------------------------------------
SELECT c.region, SUM(f.amount) AS total_amount
FROM fact_transactions f
JOIN dim_date d             ON f.date_id = d.date_id
JOIN dim_customer c         ON f.customer_id = c.customer_id
JOIN dim_transaction_type t ON f.type_id = t.type_id
WHERE d.year = 2025 AND d.quarter = 1 AND t.type_name = 'Transfer'
GROUP BY c.region
ORDER BY 2 DESC;

-- -----------------------------------------------------------------------------
-- 8. Drill-through: full transaction list for one customer in a given month
--    OLAP operation: drill-through (aggregate report -> raw fact rows)
-- -----------------------------------------------------------------------------
SELECT f.transaction_id, d.calendar_date, f.amount, f.currency,
       t.type_name, ch.channel_name
FROM fact_transactions f
JOIN dim_date d              ON f.date_id = d.date_id
JOIN dim_customer c          ON f.customer_id = c.customer_id
JOIN dim_transaction_type t  ON f.type_id = t.type_id
JOIN dim_channel ch          ON f.channel_id = ch.channel_id
WHERE c.full_name = 'Ivanov I.I.' AND d.year = 2025 AND d.month = 1;

-- -----------------------------------------------------------------------------
-- 9. Each channel's share of total transaction volume
--    OLAP operation: window function without GROUP BY collapse (SUM ... OVER ())
-- -----------------------------------------------------------------------------
SELECT channel_name, txn_count, total_amount,
       total_amount * 100.0 / SUM(total_amount) OVER () AS pct_of_total
FROM (
    SELECT ch.channel_name, COUNT(*) AS txn_count, SUM(f.amount) AS total_amount
    FROM fact_transactions f
    JOIN dim_channel ch ON f.channel_id = ch.channel_id
    GROUP BY ch.channel_name
) t
ORDER BY total_amount DESC;

-- -----------------------------------------------------------------------------
-- 10. Average transactions per client, by segment and transaction type
--     OLAP operation: multi-dimensional aggregation with a derived ratio metric
-- -----------------------------------------------------------------------------
SELECT c.segment, t.type_name,
       COUNT(*) * 1.0 / COUNT(DISTINCT c.customer_id) AS avg_tx_per_client
FROM fact_transactions f
JOIN dim_customer c         ON f.customer_id = c.customer_id
JOIN dim_transaction_type t ON f.type_id = t.type_id
JOIN dim_date d              ON f.date_id = d.date_id
WHERE d.year = 2025 AND d.quarter = 1
GROUP BY c.segment, t.type_name;
